export function ContextualToolbar({
  selectedText = "{{selectedText}}",
  label = "{{label}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
  placement = "{{placement}}",
  visible = {{visible}},
}) {
  const bg = { light: "#FAF7F2", dark: "#241430", brand: "#D9C8F0" }[variant] ?? "#241430";
  const pos = placement === "below" ? { top: "calc(100% + 10px)" } : { bottom: "calc(100% + 10px)" };
  return (
    <div style={{ display: "grid", placeItems: "center", minHeight: 260, borderRadius: 12, padding: 24, boxSizing: "border-box" }}>
      <div style={{ position: "relative", maxWidth: 420, font: "15px/1.7 system-ui, sans-serif", color: "#241430" }}>
        <p style={{ margin: 0 }}>
          Great writing starts with clear{" "}
          <span style={{ background: "#BFD9F255", borderRadius: 3, padding: "0 2px" }}>{selectedText}</span>{" "}
          and a consistent voice throughout the document.
        </p>
        {visible && (
          <div role="toolbar" aria-label={label} style={{ position: "absolute", left: "50%", transform: "translateX(-50%)", display: "flex",
            alignItems: "center", gap: 4, padding: "6px 8px", borderRadius: 10, boxShadow: "0 10px 24px rgba(36,20,48,.28)", background: bg, ...pos }}>
            <button type="button" aria-label="Bold" style={{ background: "none", border: "none", cursor: "pointer", fontWeight: 600, fontSize: 13, padding: "5px 8px", borderRadius: 6, color: accent }}><strong>B</strong></button>
            <button type="button" aria-label="Italic" style={{ background: "none", border: "none", cursor: "pointer", fontWeight: 600, fontSize: 13, padding: "5px 8px", borderRadius: 6, color: accent }}><em>I</em></button>
            <span aria-hidden="true" style={{ width: 1, height: 16, background: "currentColor", opacity: .25 }} />
            <button type="button" aria-label="Add link" style={{ background: "none", border: "none", cursor: "pointer", padding: "5px 8px", borderRadius: 6, color: accent, display: "grid", placeItems: "center" }}>
              <svg viewBox="0 0 20 20" width="15" height="15" aria-hidden="true">
                <path d="M8.5 11.5 11.5 8.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
                <path d="M9.5 6.5 11 5a2.5 2.5 0 0 1 3.5 3.5L13 10" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
                <path d="M10.5 13.5 9 15a2.5 2.5 0 0 1-3.5-3.5L7 10" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
              </svg>
            </button>
            <button type="button" aria-label="Add comment" style={{ background: "none", border: "none", cursor: "pointer", padding: "5px 8px", borderRadius: 6, color: accent, display: "grid", placeItems: "center" }}>
              <svg viewBox="0 0 20 20" width="15" height="15" aria-hidden="true">
                <path d="M3 4.5h14v9H8l-3 3v-3H3z" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />
              </svg>
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
